      "reason": "The title explicitly identifies the report as a systematic review (and meta-analysis)."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Energy use and its contributors in hotel buildings: A systematic review and meta-analysis.",
      "reason": "The title conveys the main objective: energy use and its contributors in hotel buildings (population/topic and exposure)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
