{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "The selection of the meta-analysis variables was done from four dimensions that were indicated in the studies: building characteristics, economics, social, and environmental ... The selected contributors to energy use in hotels and their frequency in sampled studies are presented in Table 1.",
      "reason": "The outcome (energy use in hotel buildings) and all contributor variables (independent variables) are listed and organized into defined dimensions (building, economic, social, environmental), with S2 Table listing retrieved independent variables."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No time frame of measurement (e.g., measurement periods or time points for energy use or contributors) is specified for the outcomes; only study-level 'period of study' is mentioned as a moderator, not outcome measurement timing."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "If the same study presents more than two correlation coefficients in nearby geographic areas, e.g., the same country, then only the two more representative samples were incorporated in the meta-analysis.",
      "reason": "The manuscript describes rules indicating that not all compatible results were collected (e.g., selecting only representative samples), but it never explicitly states whether all compatible results within each outcome domain were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "When papers used the same sample as another study, the more representative (precise) one was maintained in the analysis as the dataset ... In case different operationalization of the same variable in a study ... the two correlation outcomes were considered only if effect sizes appeared more than ten times, otherwise, raw energy data was used.",
      "reason": "The process for selecting which results to collect when multiple compatible results existed is clearly described with decision rules."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "the protocol for this systematic review was registered on the Open Science Framework platform",
      "reason": "No changes to outcome-domain inclusion, definitions, or importance are reported anywhere in the retrieved evidence; a registered protocol exists and no deviations are described."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "the protocol for this systematic review was registered on the Open Science Framework platform",
      "reason": "No changes to the processes for selecting results within outcome domains are reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "These three independent variables were the only ones with more than ten effect sizes and were the only variables that could be analyzed for publication bias.",
      "reason": "Floor area, guestrooms, and occupancy receive focused analysis (subgroup, meta-regression, cumulative analyses), implicitly prioritizing them, but the manuscript does not explicitly state which outcomes were considered most important for interpreting conclusions or a rationale for that prioritization."
    }
