  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Study characteristics that could serve as moderators were collected in the data extraction process and include publication year, approximated geographic location (latitude, longitude, climate zone, and continental area), sample size, period of study, publication year, if the study was supported by theory or not, main method, journal quality, predominant energy source, and hotel category (star rating).",
      "reason": "Variables sought are listed (independent variables such as floor area, occupancy rate, number of rooms, carbon intensity, water use in text_6, and moderator characteristics in text_7, with S2 Table referenced), but most variables are not formally defined; definitions are scattered and rely on supplementary files."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "In case different operationalization of the same variable in a study, i.e., reports with the use of raw energy data and/or the use of normalized energy data, the two correlation outcomes were considered only if effect sizes appeared more than ten times, otherwise, raw energy data was used.",
      "reason": "The manuscript describes decision rules for ambiguous or overlapping study information (duplicate samples, repeated data, differing operationalizations), which function as assumptions about unclear information, but these are framed as eligibility/analysis rules rather than an explicit description of assumptions about missing or unclear data items."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No tool or instrument used to determine which data items to collect (e.g., a data extraction form or template) is cited; PRISMA-P is cited for protocol development, not for data item selection."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Aiming to present an estimate of confidence in this meta-analysis, cumulative evidence was applied as an evaluation grade based on objective elements that could represent the risk of bias in individual studies.",
      "reason": "No validated risk-of-bias tool (e.g., ROBINS-I, RoB 2) is named; only a custom grading approach is described, so the tool used is not specified in the standard sense."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The elements are the use of primary or secondary data, sample size, the level of support for a theory, the period of analysis, and the amplitude of the study site.",
      "reason": "The components/items of the custom assessment are explicitly listed."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The five elements were considered at equal rates of 20% each. Individual studies received grades based on the five assumptions, and the mean value of all studies is the estimated evidence of the review.",
      "reason": "An overall judgement (cumulative evidence grade) is made and the derivation rules (weighting and scoring per element) are reported."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No adaptation of an existing risk-of-bias tool is reported; the evidence describes a bespoke grading scheme, not a modified validated tool."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "In sample size, if a study brings a sample of 200 objects or more, it is represented as '10', and so on for other values (e.g., a sample of 80 is classified as 4.00).",
      "reason": "A newly developed grading scheme is described in detail, but no statement indicates it was made publicly accessible (S1 Appendix is a meta-analysis coding book, not the RoB tool)."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "MISSING",
      "chunk_id": null,
